style.css:
:root {
  --var-opacity-option: 0.4;
  --var-color-saturation: 1.6;
  --var-contrast: 1;

  --snow-color: rgba(255, 255, 255, 0.85);
  --snow-glow: rgba(255, 255, 255, 0.6);
}

/*  transparency baseline */
body {
  background: transparent;
}

/* Falling snow overlay */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;

  background-image:
    radial-gradient(2.8px 2.8px at 10% 0%, var(--snow-color), transparent),
    radial-gradient(2.1px 2.1px at 25% 10%, var(--snow-color), transparent),
    radial-gradient(2.8px 2.8px at 40% 0%, var(--snow-color), transparent),
    radial-gradient(1.4px 1.4px at 55% 5%, var(--snow-color), transparent),
    radial-gradient(2.8px 2.8px at 70% 0%, var(--snow-color), transparent),
    radial-gradient(2.1px 2.1px at 85% 10%, var(--snow-color), transparent);

  background-repeat: repeat;
  background-size: 200px 200px;

  animation: fallingSnow 18s linear infinite;
  filter: drop-shadow(0 0 4px var(--snow-glow)) blur(0.2px);
}

@keyframes fallingSnow {
  from {
    background-position: 0 -100%;
  }
  to {
    background-position: 0 100%;
  }
}
